import type { RetryConfig, ResilanceConfig, CircuitBreakerConfig, BulkheadConfig, FallbackConfig } from "./resilance.config";
import {
    type IPolicy,
    type IDefaultPolicyContext,
    retry,
    handleWhen,
    handleAll,
    RetryPolicy,
    IterableBackoff,
    ExponentialBackoff,
    ConstantBackoff,
    circuitBreaker,
    type IBackoffFactory,
    type IRetryBackoffContext,
    SamplingBreaker,
    ConsecutiveBreaker,
    CountBreaker,
    wrap,
    NoopPolicy,
    bulkhead,
    fallback,
    CircuitBreakerPolicy,
    BulkheadPolicy,
    FallbackPolicy,
    type ICountBreakerOptions,
    type ISamplingBreakerOptions,
} from "cockatiel";

export const resiliencePolicyBuilder = <
    T, 
    S = void, 
    R = unknown, 
    A extends IPolicy<IDefaultPolicyContext, R> = IPolicy<IDefaultPolicyContext, R>
>(config: ResilanceConfig<T, S, R>): A => {
    const policies: Array<IPolicy<IDefaultPolicyContext, R> | undefined> = [
        config.retry && buildRetryPolicy(config.retry),
        config.circuitBreaker && buildCircuitBreakerPolicy(config.circuitBreaker),
        config.bulkhead && buildBulkheadPolicy(config.bulkhead),
        config.fallback && buildFallbackPolicy(config.fallback),
    ];

    const filteredPolicies = policies.filter(Boolean) as Array<IPolicy<IDefaultPolicyContext, R>>;

    if (filteredPolicies.length === 0) {
        return new NoopPolicy() as unknown as A;
    }

    return wrap(...filteredPolicies) as unknown as A;
}

const isBackoffFactory = (value: unknown): value is IBackoffFactory<IRetryBackoffContext<unknown>> =>
    typeof value === 'object' &&
    value !== null &&
    'next' in value &&
    typeof (value as { next: unknown }).next === 'function';

export const buildRetryPolicy = <T, S = void, R = unknown>(config: RetryConfig<T, S>): RetryPolicy => {
    const backoff: IBackoffFactory<IRetryBackoffContext<T>> = 
        typeof config.backoff === 'number' ? new ConstantBackoff(config.backoff)
        : config.backoff instanceof Array ? new IterableBackoff(config.backoff) 
        : isBackoffFactory(config.backoff) ? config.backoff  
        : new ExponentialBackoff(config.backoff)

    const policy = retry(
        config.shouldRetry ? handleWhen(config.shouldRetry) : handleAll, 
        { 
            maxAttempts: config.maxAttempts, 
            backoff
        }
    );

    if (config.onSuccess) {
        policy.onSuccess(config.onSuccess);
    }
    if (config.onFailure) {
        policy.onFailure(config.onFailure);
    }
    if (config.onRetry) {
        policy.onRetry(config.onRetry);
    }
    if (config.onGiveUp) {
        policy.onGiveUp(config.onGiveUp);
    }

    return policy;
}

const isCountBreakerOptions = (breaker: number | ICountBreakerOptions | ISamplingBreakerOptions): breaker is ICountBreakerOptions =>
    typeof breaker === 'object' && 'size' in breaker;

export const buildCircuitBreakerPolicy = (config: CircuitBreakerConfig): CircuitBreakerPolicy => {
    const breaker = 
        typeof config.breaker === 'number' 
            ? new ConsecutiveBreaker(config.breaker)
            : isCountBreakerOptions(config.breaker)
                ? new CountBreaker(config.breaker)
                : new SamplingBreaker(config.breaker);

    const policy = circuitBreaker(
        config.shouldBreak ? handleWhen(config.shouldBreak) : handleAll,
        {
            breaker,
            halfOpenAfter: config.halfOpenAfter,
            initialState: config.initialState,
        }
    );

    if (config.onBreak) {
        policy.onBreak(config.onBreak);
    }
    if (config.onReset) {
        policy.onReset(config.onReset);
    }
    if (config.onHalfOpen) {
        policy.onHalfOpen(config.onHalfOpen);
    }
    if (config.onStateChange) {
        policy.onStateChange(config.onStateChange);
    }
    if (config.onSuccess) {
        policy.onSuccess(config.onSuccess);
    }
    if (config.onFailure) {
        policy.onFailure(config.onFailure);
    }

    return policy;
}

export const buildBulkheadPolicy = (config: BulkheadConfig): BulkheadPolicy => {
    const policy = bulkhead(config.limit, config.queue);

    if (config.onSuccess) {
        policy.onSuccess(config.onSuccess);
    }
    if (config.onFailure) {
        policy.onFailure(config.onFailure);
    }
    if (config.onReject) {
        policy.onReject(config.onReject);
    }

    return policy;
}

export const buildFallbackPolicy = <R = unknown>(config: FallbackConfig<R>): FallbackPolicy<R> => {
    const valueOrFactory = typeof config.valueOrFactory === 'function'
        ? config.valueOrFactory as () => Promise<R> | R
        : () => config.valueOrFactory as R;

    const policy = fallback(
        config.shouldFallback ? handleWhen(config.shouldFallback) : handleAll,
        valueOrFactory
    );

    if (config.onSuccess) {
        policy.onSuccess(config.onSuccess);
    }
    if (config.onFailure) {
        policy.onFailure(config.onFailure);
    }

    return policy;
}

src/resilence.policy.ts.source:
import { ExponentialBackoff } from "cockatiel";
import type { CircuitBreakerConfig, ResilanceConfig, RetryConfig } from "./client/resilance.config";
import { isRetryableError, SAFE_HTTP_METHODS } from "./shouldRetry";

export enum ResilencePresets {
    CONSERVATIVE = 'conservative',
    RESTFULL = 'restfull',
    LOW_QUALITY = 'low-quality',
}

// Method names MUST be uppercased to match `isMethodInList`, which uppercases
// the request's `error.config.method` before lookup. Mixing case here silently
// disables retries for the extended verbs and breaks the RESTFULL preset.
const IDEMPOTENT_HTTP_METHODS = SAFE_HTTP_METHODS.concat(['PUT', 'DELETE']);

export const safeMethodsRetry: RetryConfig<unknown> = {
    maxAttempts: 3,
    backoff: new ExponentialBackoff(),
    shouldRetry: error => isRetryableError(error, SAFE_HTTP_METHODS),
}

// cockatiel's `SamplingBreaker` validates `threshold` strictly within `(0, 1)`
// — i.e. `0 < threshold < 1`. The previous value `1` triggered a `RangeError`
// at construction time, so any consumer building this preset (including
// `RestClient`'s default config path) crashed before serving a single request.
// `0.99` keeps the original "trip on near-total failure" intent while
// satisfying the breaker's contract.
export const defaultCircutBreaker: CircuitBreakerConfig = {
    halfOpenAfter: 60 * 1000,
    breaker: {
        threshold: 0.99,
        duration: 60 * 1000,
        minimumRps: 100
    },
}

export const resiliencePolicyPresets: Record<ResilencePresets, ResilanceConfig<number, void, number>> = {
    [ResilencePresets.CONSERVATIVE]: {
        retry: safeMethodsRetry,
        circuitBreaker: defaultCircutBreaker,
    },
    [ResilencePresets.RESTFULL]: {
        retry: {
            ...safeMethodsRetry,
            shouldRetry: error => isRetryableError(error, IDEMPOTENT_HTTP_METHODS),
        },
        circuitBreaker: defaultCircutBreaker
    },
    [ResilencePresets.LOW_QUALITY]: {
        retry: safeMethodsRetry,
        circuitBreaker: defaultCircutBreaker
    },
};

src/shouldRetry.ts.source:
import { isAxiosError, type AxiosError } from "axios";

export const SAFE_HTTP_METHODS = ['GET', 'HEAD', 'OPTIONS'];

/**
 * Retry policy for network errors and 5xx server errors.
 *
 * This is a simplified retry condition suitable for non-idempotent requests (POST, PATCH).
 * It retries on:
 * - Network errors (ENOTFOUND, ECONNABORTED, ECONNRESET, etc.) - uses isNetworkOrInternalError
 * - Server errors (5xx) - temporary server issues
 *
 * It does NOT retry on:
 * - Client errors (4xx) - bad request, authentication, validation errors
 *
 */
export function isRetryableError(error: Error, methods: string[] = SAFE_HTTP_METHODS): boolean {
    // Not an axios error - retry (types/parsing error)
    if (!isAxiosError(error)) {
        return true;
    }

    // Retry only for idempotent methods
    if (!isMethodInList(error, methods)) {
        return false;
    }

    // Network/timeout errors (no response)
    return isNetworkOrInternalError(error);
}

export function isMethodInList(error: AxiosError, list: string[]): boolean {
    const method = error.config?.method;
    if (!method) {
        // Cannot determine if the request can be retried
        return false;
    }

    return list.includes(method.toUpperCase());
}

export function isNetworkOrInternalError(error: AxiosError): boolean {
    return isNetworkError(error) || isInternalError(error);
}

// Based on https://github.com/sindresorhus/is-retry-allowed/blob/main/index.js
const CODE_EXCLUDE_LIST = [
    'ERR_CANCELED', 
    'ECONNABORTED',
    'ENOTFOUND',
	'ENETUNREACH',

	// SSL errors from https://github.com/nodejs/node/blob/fc8e3e2cdc521978351de257030db0076d79e0ab/src/crypto/crypto_common.cc#L301-L328
	'UNABLE_TO_GET_ISSUER_CERT',
	'UNABLE_TO_GET_CRL',
	'UNABLE_TO_DECRYPT_CERT_SIGNATURE',
	'UNABLE_TO_DECRYPT_CRL_SIGNATURE',
	'UNABLE_TO_DECODE_ISSUER_PUBLIC_KEY',
	'CERT_SIGNATURE_FAILURE',
	'CRL_SIGNATURE_FAILURE',
	'CERT_NOT_YET_VALID',
	'CERT_HAS_EXPIRED',
	'CRL_NOT_YET_VALID',
	'CRL_HAS_EXPIRED',
	'ERROR_IN_CERT_NOT_BEFORE_FIELD',
	'ERROR_IN_CERT_NOT_AFTER_FIELD',
	'ERROR_IN_CRL_LAST_UPDATE_FIELD',
	'ERROR_IN_CRL_NEXT_UPDATE_FIELD',
	'OUT_OF_MEM',
	'DEPTH_ZERO_SELF_SIGNED_CERT',
	'SELF_SIGNED_CERT_IN_CHAIN',
	'UNABLE_TO_GET_ISSUER_CERT_LOCALLY',
	'UNABLE_TO_VERIFY_LEAF_SIGNATURE',
	'CERT_CHAIN_TOO_LONG',
	'CERT_REVOKED',
	'INVALID_CA',
	'PATH_LENGTH_EXCEEDED',
	'INVALID_PURPOSE',
	'CERT_UNTRUSTED',
	'CERT_REJECTED',
	'HOSTNAME_MISMATCH'
];

export function isNetworkError(error: AxiosError) {
    if (error.response) {
        return false;
    }
    if (!error.code) {
        return false;
    }
    // Prevents retrying unsafe errors
    if (CODE_EXCLUDE_LIST.includes(error.code)) {
        return false;
    }

    return true;
}


export function isInternalError(error: AxiosError): boolean {
    return (
        error.code !== 'ECONNABORTED' &&
        (!error.response ||
            error.response.status !== undefined ||
            error.response.status === 429 ||
            (error.response.status >= 500 && error.response.status <= 599))
    );
}

src/auth/auth-rest.client.ts.source:
import type {
  AxiosRequestConfig,
  AxiosResponse,
} from 'axios'

import type { RestClient } from '../client/rest.client'
import type { AuthStrategyService } from './auth-strategy.service'
import { Authenticate } from './authenticate.decorator'

/**
 * Authenticated HTTP client. Composes a {@link RestClient} (which owns the
 * resilience policy stack) with an {@link AuthStrategyService} (which owns
 * the authentication lifecycle) and decorates every request method with
 * `@Authenticate` so that:
 *
 * 1. `authStrategy.authenticateIfNeeded()` runs before each request.
 * 2. The request config is augmented via `authStrategy.extendRequest(config)`.
 * 3. A single HTTP 401 response triggers `authStrategy.clearAuth()`,
 *    a forced re-authentication, and a single retry of the underlying
 *    {@link RestClient} call.
 *
 * Each verb is a thin forwarder to the corresponding {@link RestClient}
 * method. The class intentionally introduces NO new resilience logic — it
 * only layers authentication on top of the existing resilient transport.
 *
 * **NFR — zero `rxjs` and zero `p-retry` imports anywhere in `src/auth/`.**
 * This class does not import either: `rxjs` is consumed inside `RestClient`
 * via the `@ExecuteWithPolicy` decorator, and `p-retry` is no longer used
 * anywhere in the auth layer (the resilience pipeline owns retry semantics).
 *
 * The {@link authStrategy} field is `public readonly` because the
 * `@Authenticate` decorator reads it from the instance at call time via
 * `context.target.authStrategy` (no reflection, no DI metadata).
 */
export class AuthRestClient {
  /**
   * Public-readable authentication strategy. Required public so the
   * `@Authenticate` decorator can read it from the instance at invocation
   * time via `context.target.authStrategy`.
   */
  readonly authStrategy: AuthStrategyService

  constructor(
    private readonly restClient: RestClient,
    authStrategy: AuthStrategyService,
  ) {
    this.authStrategy = authStrategy
  }

  // Each verb is a thin forwarder to `this.restClient.<verb>(...)` decorated
  // with `@Authenticate()`. The same generic signatures as `RestClient` are
  // used so that the public surface is interchangeable from a caller's
  // perspective. The `@Authenticate` decorator handles config-arg extension
  // and 401 retry; this class adds nothing beyond delegation.

  @Authenticate()
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- mirrors RestClient.request<T = any>; switching to `unknown` would force callers to narrow `response.data` and would break API parity with the wrapped RestClient
  request<T = any>(config: AxiosRequestConfig): Promise<AxiosResponse<T>> {
